    AnalyticsPathFilter.add_member(:operator, Smithy::Schema::Shapes::ShapeRef.new(shape: AnalyticsFilterOperator, location_name: 'operator', traits: {"smithy.api#documentation" => "<p>The operation by which to filter the category. The following operations are possible:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CO</code> – Contains</p>\n            </li>\n            <li>\n               <p>\n                  <code>EQ</code> – Equals</p>\n            </li>\n            <li>\n               <p>\n                  <code>GT</code> – Greater than</p>\n            </li>\n            <li>\n               <p>\n                  <code>LT</code> – Less than</p>\n            </li>\n         </ul>\n         <p>The operators that each filter supports are listed below:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>BotAlias</code> – <code>EQ</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BotVersion</code> – <code>EQ</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>LocaleId</code> – <code>EQ</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Modality</code> – <code>EQ</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Channel</code> – <code>EQ</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    AnalyticsPathFilter.add_member(:values, Smithy::Schema::Shapes::ShapeRef.new(shape: AnalyticsFilterValues, location_name: 'values', traits: {"smithy.api#documentation" => "<p>An array containing the values of the category by which to apply the operator to filter the results. You can provide multiple values if the operator is <code>EQ</code> or <code>CO</code>. If you provide multiple values, you filter for results that equal/contain any of the values. For example, if the <code>name</code>, <code>operator</code>, and <code>values</code> fields are <code>Modality</code>, <code>EQ</code>, and <code>[Speech, Text]</code>, the operation filters for results where the modality was either <code>Speech</code> or <code>Text</code>.</p>", "smithy.api#required" => {}}))
