    CreateBotRequest.add_member(:idle_session_ttl_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: SessionTTL, location_name: 'idleSessionTTLInSeconds', traits: {"smithy.api#documentation" => "<p>The time, in seconds, that Amazon Lex should keep information about a\n         user's conversation with the bot. </p>\n         <p>A user interaction remains active for the amount of time specified.\n         If no conversation occurs during this time, the session expires and\n         Amazon Lex deletes any data provided before the timeout.</p>\n         <p>You can specify between 60 (1 minute) and 86,400 (24 hours)\n         seconds.</p>", "smithy.api#required" => {}}))
    CreateBotRequest.add_member(:bot_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagMap, location_name: 'botTags', traits: {"smithy.api#documentation" => "<p>A list of tags to add to the bot. You can only add tags when you\n         create a bot. You can't use the <code>UpdateBot</code> operation to\n         update tags. To update tags, use the <code>TagResource</code>\n         operation.</p>"}))
